fn draw(frame: &mut Frame, app: &mut App) {
    let view = app.client.view();
    let area = frame.area();
    // Claude-Code grammar: transcript owns the screen, input is a boxed bar at
    // the bottom, one status line under it.
    let [main, rule_area, input_area, hint_area] = Layout::vertical([
        Constraint::Min(0),
        Constraint::Length(1),
        Constraint::Length(1),
        Constraint::Length(1),
    ])
    .areas(area);

    draw_transcript(
        frame,
        main,
        &view,
        &mut app.cache,
        app.version,
        &app.streaming,
        app.clock.generating(),
        app.clock.running_secs(),
        app.scroll,
        &mut app.max_scroll,
        &mut app.viewport,
    );
    frame.render_widget(
        Paragraph::new("─".repeat(area.width as usize))
            .style(Style::new().fg(Color::Rgb(52, 54, 64))),
        rule_area,
    );
    draw_input(frame, input_area, app);
    draw_status(frame, hint_area, &view, app);

    if app.mode == Mode::Picker {
        draw_picker(frame, area, app);
    }
}

fn draw_input(frame: &mut Frame, area: Rect, app: &App) {
    // No box, no background: the rule above is the only separation.
    let line = if app.input.is_empty() {
        Line::from(vec![
            Span::styled("> ", Style::new().fg(ACCENT)),
            Span::styled(placeholder(app), Style::new().fg(DIM)),
        ])
    } else {
        Line::from(vec![
            Span::styled("> ", Style::new().fg(ACCENT)),
            Span::styled(app.input.clone(), Style::new().fg(TEXT)),
            Span::styled("▏", Style::new().fg(ACCENT)),
        ])
    };
    frame.render_widget(Paragraph::new(line), area);
}

fn draw_status(frame: &mut Frame, area: Rect, view: &View, app: &App) {
    let typing = match app.mode {
        Mode::Picker => app.picker.query_typed(),
        Mode::Chat => !app.input.is_empty(),
    };
    let session = view
        .rows
        .iter()
        .find(|row| row.selected)
        .map(|row| row.text.clone())
        .unwrap_or_else(|| "no session".into());
    let clock = app.clock.label();
    let right = if clock.is_empty() {
        format!("  │  {session} · {}", app.model)
    } else {
        format!("  │  {session} · {} · {clock}", app.model)
    };

    // Left and right share one row: truncate the hints, never overlap.
    let reserve = right.chars().count() + 2;
    let room = (area.width as usize).saturating_sub(reserve);
    let left: String = hints(app.mode, typing, app.clock.generating())
        .chars()
        .take(room)
        .collect();
    frame.render_widget(Paragraph::new(left).style(Style::new().fg(DIM)), area);
    frame.render_widget(
        Paragraph::new(right)
            .alignment(Alignment::Right)
            .style(Style::new().fg(DIM)),
        area,
    );
}

fn placeholder(_app: &App) -> &'static str {
    "type a message"
}

fn draw_header(frame: &mut Frame, area: Rect, view: &View, app: &App) {
    let title = view
        .rows
        .iter()
        .find(|row| row.selected)
        .map(|row| row.text.clone())
        .unwrap_or_else(|| "no session · ctrl+n".into());
    frame.render_widget(
        Paragraph::new(Line::from(Span::styled(
            title,
            Style::new().fg(DIM).add_modifier(Modifier::BOLD),
        ))),
        area,
    );

    let clock = app.clock.label();
    let right = if clock.is_empty() {
        format!("{} · {}", app.model, app.status)
    } else {
        format!("{} · {clock}", app.model)
    };
    frame.render_widget(
        Paragraph::new(right)
            .alignment(Alignment::Right)
            .style(Style::new().fg(DIM)),
        area,
    );
}

fn draw_transcript(
    frame: &mut Frame,
    area: Rect,
    view: &View,
    cache: &mut Option<Cache>,
    version: u64,
    streaming: &str,
    generating: bool,
    elapsed: Option<f64>,
    scroll: u16,
    max_scroll: &mut u16,
    viewport: &mut u16,
) {
    // Two columns of air on the left; the rule below keeps the full width.
    let area = Rect {
        x: area.x + 2,
        y: area.y,
        width: area.width.saturating_sub(2),
        height: area.height,
    };

    let fresh = cache
        .as_ref()
        .is_some_and(|cache| cache.version == version && cache.width == area.width);
    if !fresh {
        *cache = Some(Cache {
            version,
            width: area.width,
            lines: rendered_transcript(view, area.width),
        });
    }
    let mut lines = cache
        .as_ref()
        .map(|cache| cache.lines.clone())
        .unwrap_or_default();

    if !streaming.is_empty() {
        lines.extend(assistant_lines(streaming, "⏺ ", area.width));
    } else if generating {
        let elapsed = elapsed.unwrap_or_default();
        lines.push(Line::from(Span::styled(
            format!("✻ {}… ({elapsed:.0}s)", spinner_word(elapsed)),
            Style::new().fg(DIM),
        )));
    }

    // History grows upward from the input line: no void between chat and prompt.
    let height = area.height as usize;
    let rows: usize = lines
        .iter()
        .map(|line| line.width().max(1).div_ceil(area.width.max(1) as usize))
        .sum();
    if rows < height {
        let mut padded = vec![Line::default(); height - rows];
        padded.append(&mut lines);
        lines = padded;
    }
    let rows = rows.max(height);
    let over = rows.saturating_sub(height) as u16;
    *max_scroll = over;
    *viewport = height as u16;
    // scroll == 0 means "pinned to the newest line".
    let top = over.saturating_sub(scroll.min(over));

    frame.render_widget(
        Paragraph::new(Text::from(lines))
            .wrap(Wrap { trim: false })
            .scroll((top, 0)),
        area,
    );
}

/// The parsed transcript: markdown per assistant turn, banded user lines.
fn rendered_transcript(view: &View, width: u16) -> Vec<Line<'static>> {
    let parsed = transcript(&view.transcript);
    let mut lines: Vec<Line<'static>> = Vec::with_capacity(parsed.len() + 8);
    let mut index = 0;
    while index < parsed.len() {
        match parsed[index].role {
            Role::User => {
                // A surface band keeps prompts visually apart from answers.
                let text = format!("> {}", parsed[index].text);
                // Padding fills the band to the pane edge, not just the text.
                let pad = (width as usize).saturating_sub(1 + text.chars().count());
                lines.push(Line::from(Span::styled(
                    format!("{text}{}", " ".repeat(pad)),
                    Style::new().fg(TEXT).bg(SURFACE),
                )));
                index += 1;
            }
            Role::Assistant => {
                let mut text = String::new();
                while index < parsed.len() && parsed[index].role == Role::Assistant {
                    if !text.is_empty() {
                        text.push('\n');
                    }
                    text.push_str(&parsed[index].text);
                    index += 1;
                }
                lines.extend(assistant_lines(&text, "⏺ ", width));
            }
        }
    }
    lines
}

fn ink_style(ink: Ink) -> Style {
    match ink {
        Ink::Plain => Style::new().fg(TEXT),
        Ink::Bold => Style::new().fg(TEXT).add_modifier(Modifier::BOLD),
        Ink::Italic => Style::new().fg(TEXT).add_modifier(Modifier::ITALIC),
        Ink::Strike => Style::new().fg(DIM).add_modifier(Modifier::CROSSED_OUT),
        Ink::Code => Style::new().fg(CODE),
        Ink::Heading => Style::new().fg(ACCENT).add_modifier(Modifier::BOLD),
        Ink::Dim => Style::new().fg(DIM),
    }
}

